import csv

with open('csv/superhero.csv', 'r') as f:
    reader = csv.DictReader(f)
    female_weights = []
    for row in reader:
        if row['gender_id'] == '2':
            weight = row['weight_kg']
            if weight and weight.strip():
                female_weights.append(float(weight))

if female_weights:
    avg_weight = sum(female_weights) / len(female_weights)
    print(f'Number of female superheroes: {len(female_weights)}')
    print(f'Average weight: {avg_weight}')
else:
    print('No female superheroes found')

